<?php
namespace Opencart\Catalog\Controller\Extension\Sixmoments\Page;
class Privacy extends \Opencart\System\Engine\Controller { public function index(): void { $this->load->language('extension/sixmoments/module/sixmoments'); $this->document->setTitle($this->language->get('six_privacy_title')); $data=$this->language->all();$data['page_title']=$this->language->get('six_privacy_title');$data['page_copy']='<h2>Data used with care</h2><p>We use contact, delivery and order data only to provide the services you request, meet legal obligations and send marketing you explicitly accepted.</p><h2>Your choices</h2><p>You may request access, correction or deletion by contacting atelier@6moments.store. Essential cookies keep the cart and checkout working; optional technologies require consent.</p>'; $data['header']=$this->load->controller('common/header');$data['footer']=$this->load->controller('common/footer');$this->response->setOutput($this->load->view('extension/sixmoments/page/legal',$data)); } }
